selector_to_html = {"a[href=\"#tracing\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Tracing<a class=\"headerlink\" href=\"#tracing\" title=\"Link to this heading\">#</a></h1><p>Capture detailed execution traces for debugging and analysis. Traces include DOM snapshots, screenshots, network activity, and console logs.</p>", "a[href=\"#debugging-failed-actions\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Debugging Failed Actions<a class=\"headerlink\" href=\"#debugging-failed-actions\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#analyzing-performance\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Analyzing Performance<a class=\"headerlink\" href=\"#analyzing-performance\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#trace-timestamp-network\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">trace-{timestamp}.network</span></code><a class=\"headerlink\" href=\"#trace-timestamp-network\" title=\"Link to this heading\">#</a></h3><p><strong>Network log</strong> - Complete network activity:</p>", "a[href=\"#best-practices\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Best Practices<a class=\"headerlink\" href=\"#best-practices\" title=\"Link to this heading\">#</a></h2><h3>1. Start Tracing Before the Problem<a class=\"headerlink\" href=\"#start-tracing-before-the-problem\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#trace-vs-video-vs-screenshot\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Trace vs Video vs Screenshot<a class=\"headerlink\" href=\"#trace-vs-video-vs-screenshot\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#start-tracing-before-the-problem\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1. Start Tracing Before the Problem<a class=\"headerlink\" href=\"#start-tracing-before-the-problem\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#use-cases\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Use Cases<a class=\"headerlink\" href=\"#use-cases\" title=\"Link to this heading\">#</a></h2><h3>Debugging Failed Actions<a class=\"headerlink\" href=\"#debugging-failed-actions\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#limitations\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Limitations<a class=\"headerlink\" href=\"#limitations\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#trace-output-files\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Trace Output Files<a class=\"headerlink\" href=\"#trace-output-files\" title=\"Link to this heading\">#</a></h2><p>When you start tracing, Playwright creates a <code class=\"docutils literal notranslate\"><span class=\"pre\">traces/</span></code> directory with several files:</p>", "a[href=\"#resources\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">resources/</span></code><a class=\"headerlink\" href=\"#resources\" title=\"Link to this heading\">#</a></h3><p><strong>Resources directory</strong> - Cached resources:</p>", "a[href=\"#clean-up-old-traces\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2. Clean Up Old Traces<a class=\"headerlink\" href=\"#clean-up-old-traces\" title=\"Link to this heading\">#</a></h3><p>Traces can consume significant disk space:</p>", "a[href=\"#what-traces-capture\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">What Traces Capture<a class=\"headerlink\" href=\"#what-traces-capture\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#trace-timestamp-trace\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">trace-{timestamp}.trace</span></code><a class=\"headerlink\" href=\"#trace-timestamp-trace\" title=\"Link to this heading\">#</a></h3><p><strong>Action log</strong> - The main trace file containing:</p>", "a[href=\"#capturing-evidence\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Capturing Evidence<a class=\"headerlink\" href=\"#capturing-evidence\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#basic-usage\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Basic Usage<a class=\"headerlink\" href=\"#basic-usage\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
